const EMPTY_PIPELINE = { generatedAt:'', summary:'', applyNow:[], reachOut:[], experiments:[], questions:[] }
const TRACK_LABELS = {job:'Roles',internship:'Internships',apprenticeship:'Apprenticeships',contract:'Contract work',freelance:'Freelance work',fellowship:'Fellowships',phd:'Funded study and PhDs',volunteer:'Volunteering',other:'Other opportunities'}
const matchTrack = item => {const explicit=String(item?.track||'').toLowerCase();if(TRACK_LABELS[explicit])return explicit;const title=item?.title||'';if(/\b(phd|doctoral)\b/i.test(title))return'phd';if(/\bintern|residency\b/i.test(title))return'internship';if(/\bapprentice\b/i.test(title))return'apprenticeship';if(/\bcontract\b/i.test(title))return'contract';if(/\bfreelance\b/i.test(title))return'freelance';if(/\bfellow|predoc\b/i.test(title))return'fellowship';if(/\bvolunteer\b/i.test(title))return'volunteer';return'job'}
const matchFitType = item => {const explicit=String(item?.fitType||'').toLowerCase();if(['strong','adjacent','stretch'].includes(explicit))return explicit;const score=Number(item?.fitScore)||0;return score>=85?'strong':score>=70?'adjacent':'stretch'}
const normalizePipeline = value => ({...EMPTY_PIPELINE,...(value||{}),applyNow:(value?.applyNow||[]).map(item=>({...item,track:matchTrack(item),fitType:matchFitType(item)}))})
